#!/usr/bin/env node
'use strict'
const fs = require('node:fs')

function anchorOf(title) {
  return title
    .toLowerCase()
    .replace(/[^a-z0-9\s-]/g, '')
    .trim()
    .replace(/\s+/g, '-')
}

function toc(markdown) {
  const seen = new Map()
  const lines = []
  let fenced = false
  for (const line of markdown.split(/\r?\n/)) {
    if (line.startsWith('```')) {
      fenced = !fenced
      continue
    }
    if (fenced) continue
    const found = /^(#{1,6})\s+(.*)$/.exec(line)
    if (found === null) continue
    const level = found[1].length
    const title = found[2].trim()
    const base = anchorOf(title)
    const count = seen.get(base) || 0
    seen.set(base, count + 1)
    const anchor = count === 0 ? base : base + '-' + String(count)
    lines.push('  '.repeat(level - 1) + '- [' + title + '](#' + anchor + ')')
  }
  return lines.join('\n')
}

if (require.main === module) console.log(toc(fs.readFileSync(process.argv[2], 'utf8')))
module.exports = { toc }

